'use client';

import { useState } from 'react';
import Hero from '@/components/hero';
import LoaderLineFold from '@/components/tweenui/loader-line-fold';

export default function Page() {
  const [opened, setOpened] = useState(false);

  return (
    <LoaderLineFold
      fullscreen
      wordmark="Northwind"
      location="Oslo"
      timeZone="Europe/Oslo"
      credit="Outdoor gear ©2026"
      onComplete={() => setOpened(true)}
    >
      <Hero play={opened} />
    </LoaderLineFold>
  );
}
